import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { sniffImageType } from '../../src/shared/image-format';
import type { AcceptedImageType } from '../../src/shared/image-format';
import { IMAGE_SNIFF_BYTES } from '../../src/shared/config';
import {
  FIXTURE_NAMES,
  embeddedFixtureBytes,
  fixtureBytes,
  type ImageFixture,
} from '../fixtures/images';

/**
 * The fixtures themselves.
 *
 * A test that drops a "3 MB PNG" is only worth what the file it drops is worth, so
 * these bytes are generated by `make-fixtures.mjs`, checked in, and — because the
 * worker pool runs inside workerd and cannot read this directory — copied into
 * `embedded.ts` by the same script. This file is what stops the two copies, and the
 * headers the whole story's typing rests on, from drifting.
 */

const EXPECTED_SNIFF: Record<ImageFixture, AcceptedImageType | null> = {
  'photo.png': 'image/png',
  'screenshot.png': 'image/png',
  'photo.jpg': 'image/jpeg',
  'photo.webp': 'image/webp',
  'animated.gif': 'image/gif',
  // Truncated in its middle, so the header still claims PNG: whether it decodes is a
  // browser question (TC-29), not a signature question.
  'corrupt.png': 'image/png',
  'document.pdf': null,
  'fake.png': null, // the same PDF bytes, wearing a .png name
  'script.svg': null,
};

describe('the image fixtures', () => {
  it('are every one of them the bytes the embedded copy carries', async () => {
    // The worker pool gets its fixtures from `embedded.ts`; if the two ever disagree,
    // the integration tests are testing different files from the browser tests.
    for (const name of FIXTURE_NAMES) {
      const onDisk = new Uint8Array(readFileSync(new URL(`../fixtures/images/${name}`, import.meta.url)));
      const embedded = await embeddedFixtureBytes(name);
      expect(embedded, name).toBeDefined();
      expect(embedded, name).toEqual(onDisk);
    }
  });

  it('say what they are, by their first bytes alone', async () => {
    for (const name of FIXTURE_NAMES) {
      const head = (await fixtureBytes(name)).subarray(0, IMAGE_SNIFF_BYTES);
      expect(sniffImageType(head), name).toBe(EXPECTED_SNIFF[name]);
    }
  });

  it('cover the range the PRD names: an image, a huge image, and two that are not images', async () => {
    const sizes = Object.fromEntries(
      await Promise.all(
        FIXTURE_NAMES.map(async (name) => [name, (await fixtureBytes(name)).byteLength] as const),
      ),
    );
    expect(sizes['photo.png']).toBeLessThan(100_000);
    // `screenshot.png` is the "large but accepted" case, and it is still under the limit.
    expect(sizes['screenshot.png']).toBeGreaterThan(100_000);
    expect(sizes['corrupt.png']).toBeGreaterThan(0);
    expect(sizes['fake.png']).toBeLessThan(1000); // a PDF is not big, just not an image
  });
});
